/* @lc app=leetcode id=2019 lang=kotlin */ class Solution { fun f(i: Int, j: Int, nums: List<Int>, ops: List<Char>, memo: HashMap<Pair<Int, Int>, Set<Int>>): Set<Int> = memo.getOrPut(i to j) { if (i == j) setOf(nums[i]) else (i until j).flatMap { k -> f(i, k, nums, ops, memo).flatMap { a -> f(k + 1, j, nums, ops, memo).map { b -> if (ops[k] == '+') a + b else a * b } } }.filter { it <= 1000 }.toSet() } fun scoreOfStudents(s: String, answers: IntArray): Int = s.split(Regex("[+*]")).map { it.toInt() }.let { nums -> s.filter { it == '+' || it == '*' }.toList().let { ops -> f(0, nums.size - 1, nums, ops, HashMap()).let { all -> s.split('+').map { t -> t.split('*').fold(1) { a, b -> a * b.toInt() } }.sum().let { c -> answers.map { a -> if (a == c) 5 else if (a in all) 2 else 0 }.sum() } } } } }